function log(text){state.events.unshift({text,t:state.t});state.events=state.events.slice(0,25);$('feed').innerHTML=state.events.slice(0,8).map(e=>`<div class="feed-line"><time>${clock(e.t)}</time><span>${e.text}</span></div>`).join('')}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');state.toastUntil=performance.now()+3800}
function clock(t){const m=17*60+12+Math.floor(t/12);return`${String(Math.floor(m/60)%24).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`}
function beep(freq=440,len=.08){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.value=.035;o.connect(g);g.connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+len);o.stop(audio.currentTime+len)}catch{}}
function openDialog(title,text,actions=[],sub='办公室里的小小人情'){if(!state.running)return;releaseInput();state.paused=true;keys={};stick={x:0,y:0};$('dialogTitle').textContent=title;$('dialogText').textContent=text;$('dialogSub').textContent=sub;$('dialogActions').innerHTML='';for(const action of actions){const b=document.createElement('button');b.textContent=action.label;b.disabled=!!action.disabled;b.onclick=()=>{closeDialog();action.run?.()};$('dialogActions').append(b)}$('dialog').classList.remove('hidden');$('closeDialog').focus()}
