 if(r?.id===1){openDialog('01仓库 · 打工人防身库存','货架上压着一块卡通板砖，标签写着：公司资产，仅限游戏里敲出小星星。拿到后才能使用背后偷袭。',[{label:state.brick?'已拿到板砖':'拿起板砖 · 解锁背后偷袭',disabled:state.brick,run:pickBrick},{label:'先不拿，继续调查',run:()=>{}}]);return}
