function simulateNPC(n,dt){if(n.down)return;
 if(n.poisonAt&&state.t>=n.poisonAt){neutralize(n,'特制茶');return}
 if(n.trapAt){const own=atRoom(n);if(n.trapKind==='ac'&&atRoom(player)?.id===own?.id){n.status='等助理离开';return}if(state.t>=n.trapAt){neutralize(n,n.trapKind==='ac'?'空调故障 + 锁门':'卡通电路陷阱');return}n.status=n.trapKind==='ac'?'空调故障中':'检查小水洼';return}
if(n.hrAt!==undefined&&state.t>=n.hrAt){route(n,{x:center(3).x+(n.hrSlot-1)*20,y:center(3).y+34},'人事约谈',75);delete n.hrAt}
 if(n.role==='maintenance'&&!state.lockFixed){
  n.angle=-Math.PI/2;
  if(n.repairUntil&&state.t>=n.repairUntil){state.lockFixed=true;n.timer=0;route(n,center(1),'收工具回仓库',999);log('咔哒！门锁修好了。老周收起工具回仓库，走廊清静下来。');toast('15 门口的维修结束了，现在可以找机会通过。')}
  return;
 }
 if(tickInvestigation(n,dt))return;
 if(n.crowdBody&&!n.path.length&&n.crowdUntil>state.t){n.moving=false;n.angle=Math.atan2(n.crowdBody.y-n.y,n.crowdBody.x-n.x);return;}
 if(n.chatUntil>state.t)return;
 if(n.path.length){
  if(n.lastPos&&dist(n,n.lastPos)<.15)n.stuckTime=(n.stuckTime||0)+dt;else n.stuckTime=0;
  n.lastPos={x:n.x,y:n.y};
  if(n.stuckTime>1.5){const goal=n.path.at(-1);n.path=findPath(n,goal);n.stuckTime=0}
  n.moving=true;if(move(n,n.path[0],dt*(n.role==='gm'?43:48)))n.path.shift();if(!n.path.length){if(['gm','vice'].includes(n.role))n.busy=false;n.timer=n.waitFor;n.moving=false;if(n.status==='送报销'){n.status=state.financeUntil>state.t?'等报销':'填报销单';n.timer=state.financeUntil>state.t?999:22}else if(n.status==='去挪车'){n.status='楼下挪车';n.hidden=true}else if(n.status==='去抽烟')n.status='楼梯间透口气';else if(n.status==='去卫生间')n.status='洗手间小憩';else if(n.status==='回工位'){n.status='在忙';n.busy=false;n.angle=Math.PI/2}else if(n.status==='总经理巡视接待区')n.status='查看接待快递';}return}
 if(n.role==='finance'&&state.financeUntil&&state.t>state.financeUntil&&n.status!=='在忙'&&n.status!=='回工位'){n.hidden=false;route(n,n.home,'回工位',10);log('柚子挪完车回来了，等待报销的同事终于松了口气。');state.financeUntil=0;return}
 if(n.status==='等报销'){if(state.financeUntil>state.t)return;n.status='填报销单';n.timer=13}
 n.timer-=dt;n.moving=false;
 if(n.role==='gm')n.angle=Math.PI+Math.sin(state.t*.32)*.6;
 if(n.role==='worker'&&!n.busy)n.angle=(n.look<3?-Math.PI/2:Math.PI/2)+Math.sin(state.t*.22+n.headTurn)*.6;
 if(n.timer>0)return;
 if(['gm','vice'].includes(n.role)){planManager(n);return}
 if(n.smoker&&!n.busy){route(n,center(23),'去抽烟',8+Math.random()*7);log('阿木：工资没到，先去楼梯间看看烟会不会到账。');return}
 if(n.busy){route(n,n.home,'回工位',n.smoker?5+Math.random()*5:10+Math.random()*13);return}
 if(n.role==='worker'){if(npcs.filter(x=>x.role==='worker'&&x.busy).length>=3){n.timer=6+Math.random()*8;return}const roll=.34+(n.nextVisit++%2)*.34;if(roll<.32){route(n,center(23),'去抽烟',12+Math.random()*8);log(`${n.name}去 23 楼梯间透口气，那里暂时有人。`)}else if(roll<.66){const id=Math.random()<.5?18:20;route(n,center(id),'去卫生间',7+Math.random()*9);log(`${n.name}离开 G01，去 ${id} 卫生间。`)}else{route(n,center(2),'送报销',20);n.waitRoom=2;log(`${n.name}去财务部送报销，回程也要小心。`)}}
  else n.timer=18+Math.random()*12;
}
function vision(n){return n.role==='gm'?175:n.role==='vice'?145:115}
function canDetect(n){return ['gm','vice'].includes(n.role)||!!n.smoker}
function sees(n){if(!canDetect(n))return false;if(state.graceUntil>state.t||(state.hiding&&dist(n,player)>24)||(n.role==='maintenance'&&gateActive()))return false;if(n.down||n.ally||n.hidden||n.chatUntil>state.t)return false;const d=dist(n,player);if(d>vision(n))return false;const a=Math.atan2(player.y-n.y,player.x-n.x),da=Math.atan2(Math.sin(a-n.angle),Math.cos(a-n.angle));return(d<20||Math.abs(da)<.68)&&lineClear(n,player)}
function tickDetection(observers,dt){let trigger=null;for(const n of npcs){if(!canDetect(n)||n.down||n.hidden){n.awareness=0;continue}if(n.smoker){n.awareness=observers.includes(n)?1:0}else{n.awareness=Math.max(0,Math.min(1,(n.awareness||0)+(observers.includes(n)?dt/2.5:-dt/.9)))}if(n.awareness>=1&&observers.includes(n))trigger??=n}state.risk=Math.max(0,...npcs.filter(canDetect).map(n=>n.awareness||0));return trigger}
function finish(win,reason){if(win){tickContracts();const bonus=state.alarmCount===0?200:0;state.score+=bonus;state.finalBonus=bonus;const cleared=state.contracts.filter(c=>state.rewarded[c.id]).length;state.grade=state.alarmCount===0&&cleared===2?'S':state.alarmCount<2?'A':state.alarmCount<5?'B':'C';try{const previous=Number(localStorage.getItem('officeBestScore')||0);state.bestScore=Math.max(previous,state.score);localStorage.setItem('officeBestScore',String(state.bestScore))}catch{state.bestScore=state.score}}state.over=true;state.paused=true;player.path=[];keys={};$('dialogTitle').textContent=win?'目标完成，漂亮撤离！':'差一点，就到周末模式了。';$('dialogText').textContent=win?`你从${reason}悄悄离开，用时 ${Math.floor(state.t)} 秒。\n评价 ${state.grade} · 本局 ${state.score} 分 · 最佳 ${state.bestScore} 分\n支线 ${state.contracts.filter(c=>state.rewarded[c.id]).length}/2 · 论战获胜 ${state.battlesWon} 场 · 无警报奖励 ${state.finalBonus} 分\n完成 ${state.kills} 次目标行动，收集 ${Object.keys(state.story.witnesses).length}/14 位同事证言，借了 ${state.stats.tricks} 次小智慧，收获 ${state.coalAlly?'一位奶茶盟友':'自己人的温柔掩护'}。\n${state.story.step===4?(state.story.choice==='solidarity'?'结局 · 全员的周五：欠薪底单被公开，牛马互助群正式上线。':'结局 · 安静的默契：你留下了工资底单，副总再也不能说没看到。'):'结局 · 一个人的晚霞：你离开了，但大家的工资还没到账。下次打开手机调查真相。'}`:`${reason}\n别着急，每一次重来，都是更熟悉同事们的日常。试试让 G01 的人先去谈心，或者绕过他们的视野。`;$('dialogSub').textContent=win?'下班快乐 · 愿你今天的晚风很温柔':'被发现了 · 同事正在喊你回来';$('dialogActions').innerHTML='';const b=document.createElement('button');b.textContent=win?'再抽一份任务，继续复仇':'再试一次，我有新主意';b.onclick=()=>{$('dialog').classList.add('hidden');$('intro').classList.remove('hidden');state.running=false;state.over=false;state.paused=false};$('dialogActions').append(b);$('dialog').classList.remove('hidden');beep(win?880:220,.25)}
function update(dt){if(!state.running||state.paused||state.over)return;state.t+=dt;const dx=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)+stick.x,dy=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0)+stick.y;player.moving=false;const quiet=sneak||keys.Shift,spd=quiet?62:112;
 const beforeMove={x:player.x,y:player.y};if(Math.hypot(dx,dy)>.001){state.hiding=false;player.path=[];const len=Math.hypot(dx,dy);move(player,{x:player.x+dx/len*50,y:player.y+dy/len*50},spd*dt*Math.min(1,len));player.moving=true}else if(player.path.length){state.hiding=false;player.moving=true;if(move(player,player.path[0],spd*dt))player.path.shift()}
 player.moving=dist(player,beforeMove)>.01;if(state.paused)return;
 tickOfficeEvents();tickSocial();tickContracts();
 for(const n of npcs)simulateNPC(n,dt);
 tickCrowds();if(state.paused)return;
 const observers=npcs.filter(sees);const detected=tickDetection(observers,dt);if(detected){startBattle(detected,'caught');return}
 const r=atRoom(player);if(r?.id===21&&player.y>room(21).y+40&&state.t>(state.closedToast||0)){toast('展厅封闭，此路不通。请走 22 电梯井或 23 楼梯间。');state.closedToast=state.t+10}
 if(r&&[22,23].includes(r.id)&&isIn(player,r,12)){if(!state.bossDone){if(state.t>(state.exitToast||0)){toast('主要目标尚未完成：先对总经理或副总经理完成一次背后突袭。');state.exitToast=state.t+6}}else if(!state.parcel){if(state.t>(state.exitToast||0)){toast('还没拿04接待区的证据快递，每局必须带走。');state.exitToast=state.t+8}}else if(state.mode==='master'&&!state.coalAlly){if(state.t>(state.exitToast||0)){toast('奶茶外交还没完成：把奶茶送给 16 的阿炭吧。');state.exitToast=state.t+8}}else{const guard=npcs.find(n=>canDetect(n)&&!n.down&&!n.ally&&!n.hidden&&dist(n,player)<45&&lineClear(n,player));if(!guard)finish(true,r.id===22?'22 电梯井':'23 楼梯间');else if(state.t>(state.exitToast||0)){toast(`${guard.name}就在出口旁，先等他离开再走。`);state.exitToast=state.t+4}}}
 if(state.t-uiTick>.18){uiTick=state.t;updateUI(observers)}
}
function updateUI(observers=[]){const r=atRoom(player);$('location').textContent=r?`${String(r.id).padStart(2,'0')} ${r.name}`:'办公室';$('clock').textContent=clock(state.t);$('riskText').textContent=`${Math.round(state.risk*100)}%`;if($('mobileRisk')){$('mobileRisk').textContent=`警觉 ${Math.round(state.risk*100)}%`;$('mobileTask').textContent=!state.bossDone?(state.target==='gm'?'目标：06 总经理':state.target==='vice'?'目标：08 副总经理':'目标：06 / 08 任一经理'):!state.parcel?'去 04 拿快递':state.mode==='master'&&!state.coalAlly?'给 16 送奶茶':'前往 22 / 23 开溜'};$('riskBar').style.width=`${state.risk*100}%`;$('riskBar').style.background=state.risk>.65?'#bd514b':'#db744c';$('riskHint').textContent=observers.length?'进入视野了，找墙角遮住自己！':'经理持续看到你约2.5秒才开战；躲到墙后警觉会下降。阿木仍会直接盘问开战。';if(!observers.length)$('mood').textContent=state.coalAlly?'奶茶结盟成功，今天多了一个自己人。':state.spawn===14?'身份：战略发展部 · 兼助理':'身份：技术部 · 工程师';$('levelTag').textContent={normal:'轻装开溜',errand:'快递小支线',master:'奶茶外交家'}[state.mode];$('missionTitle').textContent=state.bossDone?'目标完成，安全撤离。':'老板的下线时刻。';$('missionDesc').textContent=state.mode==='normal'?'工资失踪三个月。收集同事证言，处理随机发布的经理目标，拿走04证据快递，再从22/23撤离。':'去 04 接待区拿自己的快递，留意 06 林总的巡视。'+(state.mode==='master'?'再送一杯奶茶给 16 阿炭，交个朋友后一起打掩护。':'然后悄悄走向电梯或楼梯。');
 const tasks=[{text:`剧情 ${state.story.step+1}/5：${['到13/14核对工资约定','去 07 找副本','和财务交谈或趁她离开核对02底单','收集3位同事证言，到03决定公开或协商','处理主要目标，带着真相撤离'][state.story.step]}`,done:state.story.step===4},{text:`主要目标：${state.target==='gm'?'06 总经理':state.target==='vice'?'08 副总经理':'06 总经理 / 08 副总经理，完成其一'}`,done:state.bossDone},{text:`离开 ${state.spawn} ${room(state.spawn).name}`,done:r?.id!==state.spawn}];tasks.push({text:'必做：去 04 接待区拿证据快递',done:state.parcel});if(state.mode==='master')tasks.push({text:'给 16 阿炭送奶茶，成为盟友',done:state.coalAlly});tasks.push({text:gateActive()?'先把老周支开，打开西侧撤离通道':'老周已离开，西侧通道放行',done:!gateActive()});for(const c of state.contracts||[])tasks.push({text:`支线：${c.title} +${c.reward}`,done:!!state.rewarded[c.id]});tasks.push({text:'从 22 电梯 / 23 楼梯开溜',done:state.over});$('objectives').innerHTML=tasks.map(t=>`<li class="${t.done?'done':''}">${t.text}</li>`).join('');$('inventory').textContent=['工牌','手机',`心态 ${state.playerHp}/120`,`黑料 ×${state.coupons}`,state.workOrder?'设备报修单':null,state.tools?'十字螺丝刀':null,state.brick?'卡通板砖':null,state.tea?'珍珠奶茶':null,state.parcel?'欠薪证据快递':null,state.disguise>state.t?'忙碌文件夹':null,state.coalAlly?'阿炭的友谊':null].filter(Boolean).join(' · ');$('population').textContent=`分数 ${state.score} · 突袭 ${state.kills}`;if($('score'))$('score').textContent=`${state.score} 分`;if($('attack')){const t=attackTarget();$('attack').disabled=!t;$('attack').textContent=!state.brick?'去仓库拿砖':t?'板砖突袭':'靠近背后'};
 $('duel').disabled=!closestRival();$('hide').textContent=state.hiding?'离开藏身':'藏身';
 const interactable=r&&[3,4,7,13,14,16,21].includes(r.id)||npcs.some(n=>dist(n,player)<50&&lineClear(n,player));$('interact').disabled=!interactable;
}
// Draws a contemporary office, using clean top-down furniture geometry and CC0 Kenney character layers.
function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function text(t,x,y,size=12,color='#435b50',align='center'){ctx.font=`${size*.76/Math.max(1,view.scale)}px "PingFang SC",system-ui,sans-serif`;ctx.textAlign=align;ctx.fillStyle=color;ctx.fillText(t,x,y)}
function desk(x,y,w=39,h=22){rr(x+1,y+3,w,h,3,'#b9bfaf');rr(x,y,w,h,3,'#e8cfa6','#c7b18f');rr(x+w*.29,y+3,w*.42,9,1,'#40575d');rr(x+w*.32,y+4,w*.36,6,0,'#8fbab5');rr(x+w*.38,y+14,w*.25,4,1,'#c0c8bd');rr(x+w-8,y+14,3,4,1,'#fff7df')}
function chair(x,y){rr(x-7,y-6,14,12,4,'#718b86','#526c66');rr(x-7,y+1,14,4,2,'#57746f');ctx.strokeStyle='#526c66';ctx.beginPath();ctx.moveTo(x,y+5);ctx.lineTo(x,y+8);ctx.moveTo(x-5,y+8);ctx.lineTo(x+5,y+8);ctx.stroke()}
function plant(x,y){rr(x-6,y-2,12,11,2,'#c39e7a');for(const[a,b,r]of[[-5,-4,6],[5,-6,6],[0,-10,7]]){ctx.fillStyle=b===-10?'#88a274':'#6e9169';ctx.beginPath();ctx.ellipse(x+a,y+b,r,r*.72,-.5,0,Math.PI*2);ctx.fill()}}
