function loop(time){const dt=Math.min(.05,(time-last)/1000||0);last=time;frameDelta=dt;update(dt);draw();requestAnimationFrame(loop)}
function pickBrick(){if(atRoom(player)?.id!==1||state.brick)return false;state.brick=true;log('拿到卡通板砖，背后偷袭已解锁。');toast('背后偷袭已解锁：绕到目标背后靠近，再点突袭。');updateUI();return true}
function attackTarget(){if(!state.brick)return null;return npcs.filter(n=>!(n.role==='maintenance'&&gateActive())&&!n.down&&!n.ally&&!n.hidden&&dist(n,player)<32&&lineClear(n,player)).find(n=>{const a=Math.atan2(player.y-n.y,player.x-n.x);return Math.cos(a-n.angle)<-.1})}
function neutralize(n,method){if(n.down)return;n.ai=null;n.down=true;n.status='气势归零 · 休息中';n.path=[];n.moving=false;state.kills++;const boss=['gm','vice'].includes(n.role);state.score+=boss?500:100;if(boss&&(state.target==='either'||state.target===n.role))state.bossDone=true;log(`${method}成功：${n.name}进入小星星状态，+${boss?500:100} 分。`);toast(state.bossDone?'主要目标完成！寻找 22 / 23 安全离场。':'可选目标完成 +100 分。');beep(440,.12);updateUI()}
function attack(){if(!state.running||state.paused||state.over||state.battle)return;if(!state.brick){toast('先去01仓库拿板砖，才能解锁背后偷袭。');return}const n=attackTarget();if(!n){toast('绕到人物背后，再靠近一些。盟友不会成为目标。');return}n.down=true;n.ai=null;n.status='小星星休息中';n.path=[];n.moving=false;state.kills++;const boss=['gm','vice'].includes(n.role);state.score+=boss?500:100;if(boss&&(state.target==='either'||state.target===n.role))state.bossDone=true;const witnesses=npcs.filter(z=>canDetect(z)&&z!==n&&!z.down&&!z.ally&&!z.hidden&&dist(z,player)<150&&lineClear(z,player));if(witnesses.length){state.risk=Math.min(.95,state.risk+.45);log(`${witnesses[0].name}目击了突袭！快离开视野！`)}else log(`${n.name}化成了小星星，+${boss?500:100} 分。${state.bossDone?'主要目标完成，准备撤离！':''}`);beep(330,.12);toast(boss?'主要目标完成！可继续加分，也可立刻安全撤离。':'额外目标 +100 分，留意有没有目击者。');updateUI()}
$('attack').onclick=attack;
