 actions.push({label:'回地图，继续我的计划',run:()=>{}});openDialog(c[0],c[1]+'\n\n下一步：'+c[2]+(q.step===3&&Object.keys(q.witnesses).length<3?'\n还需要至少3位同事证言，请靠近同事互动。':'')+(q.step===2&&!safeFinance?'\n财务还在屋里，现在不能翻底单。':'')+'\n证据 '+q.evidence+' 份 · 路线：'+(q.choice==='solidarity'?'公开真相':q.choice==='quiet'?'秘密协商':'尚未选择'),actions,'工资失踪特别篇 · '+(q.step+1)+'/5');
