function showDossier(){openDialog('办公室行动手册',`你的身份：${state.spawn===13?'工程师 · 汇报 / 设备工单':'兼助理 · 签字 / 送茶协调'}\n\n【老周】挡住西侧出口通道，必须修好锁让他离开、交报修单，或论战赢后支开。闲聊不放行。\n【战斗】打弱点削 2 架势，其他流程招削 1；破防取消对方行动，接下来两招增伤。重击用‘这事有邮件吗’反弹。已读不回能减伤并免疫扣灵感。士气满 100 放劳动仲裁，证据可增强大招。重复攻击会被识破；老板半血进入二阶段。AI 做资料接甩出公司黑料有连携。\n【弱点】同事 / 财务：AI 做资料；阿炭：黑料；总经理 / 后勤：需求变更；副总 / 人事：会议连环套。\n【遭遇】经理需连续看到你约2.5秒才开战，墙体遮挡后警觉下降，阿木视线直接开战；不会因视线判负。背后偷袭先去01仓库拿板砖。其他同事可放心交谈。手机可让空座机响起引走两个人。\n\n当前办公室下一次事件：约 ${Math.max(0,Math.ceil(state.nextEvent-state.t))} 秒后。`,[{label:'了解了，按我的计划来',run:()=>{}}])}
function startBattle(n,reason='challenge'){if(!state.running||state.over||!n||n.down||n.hidden||n.ally||state.battle)return false;if(reason==='challenge'&&(dist(n,player)>60||!lineClear(n,player))){toast('靠近这位同事，才能开始职场论战。');return false}releaseInput();state.hiding=false;state.paused=true;player.path=[];keys={};stick={x:0,y:0};$('drawer').classList.add('hidden');$('dialog').classList.add('hidden');state.battle={target:n,reason,engine:Battle.create(n.role,state.spawn,{hp:state.playerHp,coupons:state.coupons,evidence:state.story.evidence,ally:state.coalAlly})};if(state.story.choice==='solidarity'&&['gm','vice'].includes(n.role)){state.battle.engine.enemyShield=12;state.battle.engine.messages.unshift('公开真相后，老板有备而来：开场获得 12 护盾。')}if(reason==='caught'){state.battle.engine.messages.unshift('你被叫住了！靠职场嘴炮争取脱身。');state.alarmCount++}if(reason==='checkpoint')state.battle.engine.messages.unshift('赢得这场论战，老周会离开门口去核对工单。');$('battleOverlay').classList.remove('hidden');renderBattle();return true}
function renderBattle(){const b=state.battle;if(!b)return;const e=b.engine,n=b.target;$('battleName').textContent=n.name;$('battleTurn').textContent=`第 ${e.turn} 回合 · ${e.phase==='enemy'?'对方行动':e.phase==='player'?(b.animating?'对方动作结算':'你的行动'):'结算'}`;$('battleIdentity').textContent=state.spawn===13?'工程师':'兼助理';$('battleHp').textContent=`心态 ${e.hp} / ${e.maxHp}`;$('battleEnemyHp').textContent=`气势 ${e.enemyHp} / ${e.maxEnemyHp}`;$('battleHpFill').style.width=e.hp/e.maxHp*100+'%';$('battleEnemyFill').style.width=e.enemyHp/e.maxEnemyHp*100+'%';$('battleEnergy').textContent=`灵感 ${e.energy}/10 · 盾 ${e.shield} · 黑料 ${e.coupons} · 士气 ${e.morale}% · 证据 ${e.evidence}`;const intent=Battle.intent(e);$('battleIntent').textContent=e.phase==='player'&&b.animating?'对方动作结算中，请稍候…':e.phase==='player'?`对方下一招：${intent[0]}${intent[1]?'（'+intent[1]+' 伤害）':''}`:e.phase==='enemy'?`对方行动：${Battle.intent(e)[0]} · 请等待出招…`:e.phase==='won'?'气势归零！你赢得了这场职场论战。':e.phase==='escaped'?'先打个圆场，这次算你溜得快。':'心态见底，今天先休息一下。';$('battleWeak').textContent=`弱点：${e.profile.weak} · ${e.broken?'破防 '+e.broken+' 招':'架势 '+e.stance+'/3'}${e.enemyShield?' · 敌盾 '+e.enemyShield:''}`;$('battleLog').innerHTML=e.messages.slice(0,4).map(t=>`<div>${t}</div>`).join('');$('battleSkills').innerHTML='';const group=b.tab||'attack';$('battleAttackTab').classList.toggle('selected',group==='attack');$('battleTacticTab').classList.toggle('selected',group==='tactics');for(const skill of Battle.available(e).filter(s=>['reply','ai','coupon','scope','meeting'].includes(s.id)===(group==='attack'))){const b=document.createElement('button');b.disabled=skill.disabled||!!state.battle?.animating;b.innerHTML=`<strong>${skill.name}</strong><span>${skill.cooldown?'冷却 '+skill.cooldown+' 回合':skill.id==='ultimate'&&e.morale<100?'士气还差 '+(100-e.morale):skill.id==='evidence'&&!e.evidence?'先在剧情中收集证据':skill.id==='coupon'&&!e.coupons?'黑料用完了':skill.id==='water'&&!e.waters?'本场已喝完':skill.cost?'灵感 −'+skill.cost:'不消耗灵感'}</span><small>${skill.detail}</small>`;b.onclick=()=>battleSkill(skill.id);$('battleSkills').append(b)}$('battleRetreat').disabled=e.phase!=='player'||!!b.animating||e.energy<3;$('battleRetreat').classList.toggle('hidden',e.phase!=='player');$('battleEnd').classList.toggle('hidden',['player','enemy'].includes(e.phase));$('battleEnd').textContent=e.phase==='won'?(b.reason==='checkpoint'?'请老周离开门口':'收下战果，回到地图'):e.phase==='escaped'?'回地图找掩护':'接受今天的加班';
 for(const [id,look]of[['battleYouCanvas',player.look??0],['battleEnemyCanvas',n.look]]){const c=$(id),g=c.getContext('2d');if(typeof g.clearRect!=='function')continue;g.clearRect(0,0,c.width,c.height);avatar(g,c.width/2,c.height-12,look,3.8,0,Math.PI/2,false)}
}
function animateFighter(id){if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;$(id).animate?.([{transform:'translateX(0)',filter:'brightness(1)'},{transform:'translateX(7px)',filter:'brightness(1.5)'},{transform:'translateX(-3px)'},{transform:'translateX(0)'}],{duration:350})}
function battleSkill(id){const b=state.battle;if(!b||b.animating||b.engine.phase!=='player')return false;const before=b.engine.enemyHp;if(!Battle.playerTurn(b.engine,id))return false;beep(470,.08);if(b.engine.enemyHp<before)animateFighter('battleEnemyCanvas');if(b.engine.phase!=='enemy'){renderBattle();return true}b.animating=true;renderBattle();
 const respond=()=>{if(state.battle!==b||b.engine.phase!=='enemy')return;const hp=b.engine.hp;Battle.enemyTurn(b.engine);if(b.engine.hp<hp){animateFighter('battleYouCanvas');beep(250,.09)}renderBattle();const ready=()=>{if(state.battle!==b)return;b.animating=false;renderBattle()};if(window.setTimeout)window.setTimeout(ready,450);else ready()};
 if(window.setTimeout)window.setTimeout(respond,900);else respond();return true}

function battleRetreat(){const b=state.battle;if(!b)return;if(!b.animating&&Battle.retreat(b.engine))renderBattle()}
function endBattle(){const b=state.battle;if(!b||['player','enemy'].includes(b.engine.phase)||b.animating)return false;const e=b.engine,n=b.target;state.playerHp=e.hp;state.coupons=e.coupons;state.story.evidence=e.evidence;$('battleOverlay').classList.add('hidden');state.battle=null;state.paused=false;keys={};stick={x:0,y:0};if(e.phase==='lost'){finish(false,`${n.name}的职场连招让你心态归零。下次记得看预告、挡重击、用弱点。`);return true}n.chatUntil=state.t+6;state.risk=e.phase==='escaped'?.5:.16;state.graceUntil=state.t+5;if(e.phase==='won'){state.battlesWon++;state.score+=30;if(b.reason==='checkpoint'){sendGuardAway('去人事核对维修工单')}else{neutralize(n,'职场论战');log(`论战奖励 +30 分。心态剩余 ${state.playerHp}，会保留到下一场。`)}}else{log(`你从与${n.name}的论战中脱身，暂时有 5 秒喘息。`)}updateUI();return true}
function closestRival(){return npcs.filter(n=>!n.down&&!n.ally&&!n.hidden&&dist(n,player)<56&&lineClear(n,player)).sort((a,b)=>dist(a,player)-dist(b,player))[0]}
$('duel').onclick=()=>{const n=closestRival();if(n)startBattle(n,n.role==='maintenance'&&gateActive()?'checkpoint':'challenge')};$('battleAttackTab').onclick=()=>{if(state.battle){state.battle.tab='attack';renderBattle()}};$('battleTacticTab').onclick=()=>{if(state.battle){state.battle.tab='tactics';renderBattle()}};$('battleRetreat').onclick=battleRetreat;$('battleEnd').onclick=endBattle;$('hide').onclick=toggleHide;

$('start').onclick=startRandomGame;document.querySelectorAll('[data-spawn]').forEach(b=>b.onclick=()=>{spawnChoice=Number(b.dataset.spawn);document.querySelectorAll('[data-spawn]').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{modeChoice=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b))});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='Escape'){if(state.battle){e.preventDefault();return}if(!$('dialog').classList.contains('hidden')&&!state.over)closeDialog();else if(state.running&&!state.over)togglePause();return}if(e.target.tagName==='BUTTON'&&e.key==='Enter')return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(k==='e'&&!e.repeat)interact();keys[k]=true});window.addEventListener('keyup',e=>{keys[e.key.length===1?e.key.toLowerCase():e.key]=false});window.addEventListener('blur',()=>{releaseInput();keys={};stick={x:0,y:0};if(state.running&&!state.paused&&!state.over){state.paused=true;$('pause').textContent='继续'}});
let mapTap=null;
canvas.addEventListener('pointerdown',e=>{if(!state.running||state.paused||Math.hypot(stick.x,stick.y)>0||e.isPrimary===false)return;mapTap={id:e.pointerId,x:e.clientX,y:e.clientY,t:performance.now()}});
canvas.addEventListener('pointermove',e=>{if(mapTap?.id===e.pointerId&&Math.hypot(e.clientX-mapTap.x,e.clientY-mapTap.y)>9)mapTap=null});
canvas.addEventListener('pointercancel',()=>{mapTap=null});
canvas.addEventListener('pointerup',e=>{const tap=mapTap;mapTap=null;if(!tap||tap.id!==e.pointerId||performance.now()-tap.t>450||!state.running||state.paused||Math.hypot(stick.x,stick.y)>0)return;const b=canvas.getBoundingClientRect(),p={x:(e.clientX-b.left-view.x)/view.scale,y:(e.clientY-b.top-view.y)/view.scale};if(!walkable(p.x,p.y,5)){toast('点房间里的地面，或用摇杆慢慢靠近。');return}const path=findPath(player,p);if(path.length)player.path=path;else toast('暂时到不了那里，先找相通的门。');canvas.focus()});
function releaseInput(){keys={};stick={x:0,y:0};player.path=[];mapTap=null;if(typeof window.dispatchEvent==='function')window.dispatchEvent(new Event('office-input-reset'))}
document.addEventListener?.('visibilitychange',()=>{if(document.hidden){releaseInput();if(state.running&&!state.paused&&!state.over){state.paused=true;$('pause').textContent='继续'}}});

