$('pause').onclick=togglePause;$('sound').onclick=()=>{sound=!sound;$('sound').textContent=`音效 ${sound?'开':'关'}`;beep(660)};$('closeDialog').onclick=closeDialog;
$('restart').onclick=()=>{if(!state.running)return;openDialog('换一个开溜计划？','当前行动会结束，你可以重新选择部门和任务。',[{label:'重新选择',run:()=>{state.running=false;state.paused=false;$('intro').classList.remove('hidden')}},{label:'继续当前行动',run:()=>{}}])};
$('help').onclick=()=>{if(!state.running){toast('选好出生部门，点击「出发」就可以开始。');return}openDialog('偷偷下班，也要有点策略','方向键 / WASD 或屏幕摇杆移动；点击地面自动寻路；轻步减慢被发现；E 互动，F 背后突袭（先去01仓库拿板砖），B 职场论战，H 藏身。\n老周会拦住西侧出口通道，必须等他真的离开才能通过。盟友可以给报修单或螺丝刀。\n论战时看下一招，护盾挡重击，AI 做资料接甩出公司黑料有连携，心态会保留到下一场。\n必须完成 06 总经理或 08 副总经理之一（开局随机发布），主要目标 +500 分，其他非盟友 +100 分。有人目击或发现倒地同事会提高警戒。\n\n橙色扇形仅属于两位经理和烟民阿木；墙壁挡视线，经理视线持续约2.5秒触发战斗，遮挡后警觉下降。\n\n13 技术部和 14 战略发展部是盟友。仓库、会议室、接待区、展厅、储藏室、神秘小屋默认无人，同事可能临时来访。\n\n手机可以提醒财务挪车、发布点心消息；拜访人事或盟友可安排约谈、打印机帮忙。接待区拿奶茶，送给 16 阿炭可以结盟。\n\n22 电梯、23 楼梯都能离开。出口附近有人时先等一等；21 是封闭走廊。接待区证据快递每局必拿。只有两位经理和阿木有探测视线，持续看到你才触发战斗；普通同事没有探测视线，可交谈收集欠薪证言。倒地人物会引来围观，靠近围观者会被审问。', [{label:'记住了，晚风在等我',run:()=>{}}])};
$('credits').onclick=()=>{if(!state.running){toast('人物：Kenney CC0。游戏灵感与来源在项目的 CREDITS.md。');return}openDialog('素材与灵感','人物后备素材：Kenney Roguelike Characters，CC0。仅使用现代服装组合。\n四方向现代人物：Kenney RPG Urban Pack，CC0。办公家具与地图由本项目绘制。\n\n玩法研究：GitHub 的 Last-Signal（墙体遮挡视野、巡逻状态机）、Echoes-of-the-Hidden（动态 NPC 日常与事件）。本游戏独立实现，没有复制它们的代码。\n\n氛围参考：温暖轻松的日常生活模拟；未使用星露谷的角色、美术或音乐。',[{label:'回到办公室',run:()=>{}}])};
