window.OfficeGame={state,pickBrick,tickDetection,startRandomGame,canDetect,beginSocial,planManager,tickSocial,tickCrowds,salaryDialogue,collectSalaryClue,releaseInput,setStick(x,y){const len=Math.hypot(x,y);stick=Number.isFinite(len)?{x:x/Math.max(1,len),y:y/Math.max(1,len)}:{x:0,y:0}},get player(){return player},get npcs(){return npcs},rooms,walls,findPath,lineClear,walkable,reset,simulateNPC,update,phone,financeAway,hrTalk,printer,giftTea,interact,closeDialog,sees,route,setMode(m,s=13){modeChoice=m;spawnChoice=s},attack,attackTarget,neutralize,gateActive,checkpointBlocks,questionGuard,sendGuardAway,helpRepair,storyDialog,startBattle,battleSkill,battleRetreat,endBattle,ringPhone,toggleHide,tickContracts,investigate,updateAwareness,snapshot:()=>({t:state.t,risk:state.risk,room:atRoom(player)?.id,npcs:npcs.map(n=>({name:n.name,status:n.status,ally:n.ally,x:n.x,y:n.y}))})};
